@csrf<div class="form-grid"><label>Anggota<select name="id_anggota" required><option value="">Pilih anggota</option>@foreach($anggotas as $anggota)<option value="{{ $anggota->id_anggota }}" @selected(old('id_anggota',$transaksi->id_anggota ?? '')==$anggota->id_anggota)>{{ $anggota->nis }} - {{ $anggota->nama_lengkap }}</option>@endforeach</select></label><label>Buku<select name="id_buku" required><option value="">Pilih buku</option>@foreach($bukus as $buku)<option value="{{ $buku->id_buku }}" @selected(old('id_buku',$transaksi->id_buku ?? '')==$buku->id_buku)>{{ $buku->judul_buku }} (stok {{ $buku->stok }})</option>@endforeach</select></label><label>Petugas<select name="user_id" required><option value="">Pilih petugas</option>@foreach($users as $user)<option value="{{ $user->id_user }}" @selected(old('user_id',$transaksi->user_id ?? auth()->id())==$user->id_user)>{{ $user->nama_lengkap }}</option>@endforeach</select></label><label>Tanggal Pinjam<input type="date" name="tanggal_pinjam" value="{{ old('tanggal_pinjam',isset($transaksi) ? $transaksi->tanggal_pinjam->format('Y-m-d') : date('Y-m-d')) }}" required></label><label>Tanggal Kembali<input type="date" name="tanggal_kembali" value="{{ old('tanggal_kembali',isset($transaksi) && $transaksi->tanggal_kembali ? $transaksi->tanggal_kembali->format('Y-m-d') : '') }}"></label><label>Status<select name="status" required>@foreach(['dipinjam','terlambat','dikembalikan'] as $statusItem)<option value="{{ $statusItem }}" @selected(old('status',$transaksi->status ?? 'dipinjam')===$statusItem)>{{ ucfirst($statusItem) }}</option>@endforeach</select></label><label>Denda (Rp)<input type="number" name="denda" value="{{ old('denda',$transaksi->denda ?? 0) }}" min="0" required></label></div>@include('partials.form-actions',['cancelUrl'=>route('transaksi.index')])